using DriveOS.Modules.Students.Domain.Closures;using DriveOS.SharedKernel.Identifiers;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace DriveOS.Modules.Students.Infrastructure.Persistence.Configurations;
internal sealed class EnrollmentClosureCaseConfiguration:IEntityTypeConfiguration<EnrollmentClosureCase>{public void Configure(EntityTypeBuilder<EnrollmentClosureCase>b){b.ToTable("enrollment_closures");b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasColumnName("id").HasConversion(x=>x.Value,x=>new EnrollmentClosureCaseId(x)).ValueGeneratedNever();b.Property(x=>x.OrganizationId).HasColumnName("organization_id").HasConversion(x=>x.Value,x=>new OrganizationId(x));b.Property(x=>x.StudentId).HasColumnName("student_id").HasConversion(x=>x.Value,x=>new PersonId(x));b.Property(x=>x.EnrollmentId).HasColumnName("enrollment_id").HasConversion(x=>x.Value,x=>new DraftEnrollmentId(x));b.Property(x=>x.PreviousEnrollmentStatus).HasColumnName("previous_enrollment_status").HasConversion<string>().HasMaxLength(30);b.Property(x=>x.Reason).HasColumnName("reason").HasConversion<string>().HasMaxLength(40);b.Property(x=>x.ClosureDate).HasColumnName("closure_date");b.Property(x=>x.ReasonDetail).HasColumnName("reason_detail").HasMaxLength(2000);b.Property(x=>x.Status).HasColumnName("status").HasConversion<string>().HasMaxLength(30);b.Property(x=>x.OperationalBlockId).HasColumnName("operational_block_id");b.Property(x=>x.CreatedAtUtc).HasColumnName("created_at_utc");b.Property(x=>x.CreatedByUserId).HasColumnName("created_by_user_id").HasConversion(x=>x.Value,x=>new UserId(x));b.Property(x=>x.ClosedAtUtc).HasColumnName("closed_at_utc");b.Property(x=>x.ClosedByUserId).HasColumnName("closed_by_user_id").HasConversion(x=>x.HasValue?x.Value.Value:(Guid?)null,x=>x.HasValue?new UserId(x.Value):null);b.Property(x=>x.ArchivedAtUtc).HasColumnName("archived_at_utc");b.Property(x=>x.ArchivedByUserId).HasColumnName("archived_by_user_id").HasConversion(x=>x.HasValue?x.Value.Value:(Guid?)null,x=>x.HasValue?new UserId(x.Value):null);b.Property(x=>x.RetainUntil).HasColumnName("retain_until");b.Property(x=>x.RetentionLegalBasis).HasColumnName("retention_legal_basis").HasMaxLength(1000);b.Property(x=>x.RetentionScope).HasColumnName("retention_scope").HasConversion<int>();b.Property(x=>x.ReopenedAtUtc).HasColumnName("reopened_at_utc");b.Property(x=>x.ReopenedByUserId).HasColumnName("reopened_by_user_id").HasConversion(x=>x.HasValue?x.Value.Value:(Guid?)null,x=>x.HasValue?new UserId(x.Value):null);b.Property(x=>x.ReopenJustification).HasColumnName("reopen_justification").HasMaxLength(2000);b.HasOne<DriveOS.Modules.Students.Domain.Enrollments.Enrollment>().WithMany().HasForeignKey(x=>x.EnrollmentId).OnDelete(DeleteBehavior.Restrict);b.HasOne<DriveOS.Modules.Students.Domain.Students.Student>().WithMany().HasForeignKey(x=>x.StudentId).OnDelete(DeleteBehavior.Restrict);b.HasMany(x=>x.Checks).WithOne().HasForeignKey(x=>x.EnrollmentClosureCaseId).OnDelete(DeleteBehavior.Cascade);b.Navigation(x=>x.Checks).UsePropertyAccessMode(PropertyAccessMode.Field);b.HasIndex(x=>new{x.OrganizationId,x.StudentId,x.Status});b.HasIndex(x=>new{x.EnrollmentId,x.Status});b.Ignore(x=>x.DomainEvents);}}
internal sealed class EnrollmentClosureCheckConfiguration:IEntityTypeConfiguration<EnrollmentClosureCheck>{public void Configure(EntityTypeBuilder<EnrollmentClosureCheck>b){b.ToTable("enrollment_closure_checks");b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasColumnName("id").ValueGeneratedNever();b.Property(x=>x.EnrollmentClosureCaseId).HasColumnName("enrollment_closure_id").HasConversion(x=>x.Value,x=>new EnrollmentClosureCaseId(x));b.Property(x=>x.Type).HasColumnName("type").HasConversion<string>().HasMaxLength(40);b.Property(x=>x.Status).HasColumnName("status").HasConversion<string>().HasMaxLength(20);b.Property(x=>x.Detail).HasColumnName("detail").HasMaxLength(1000);b.HasIndex(x=>new{x.EnrollmentClosureCaseId,x.Type}).IsUnique();}}
